c as (
  update catalog_products cp set
    image_url = case when v.image is not null and cp.image_url like 'https://images.pexels.com/%' then v.image else cp.image_url end,
    description = case when v.descr is not null and (coalesce(cp.description, '') = '' or length(cp.description) < 0.6 * length(v.descr)) then v.descr else cp.description end,
    updated_at = now()
  from v
  where cp.name = v.name
  returning cp.id, cp.image_url, cp.description
)
update products p set
  image_url = c.image_url,
  description = c.description,
  updated_at = now()
from c
where p.catalog_id = c.id;
